/** Adapter identity valid for the current OS GPU devices. */
export type FrameForwardingAdapterId = string & { readonly __frameForwardingAdapterId: unique symbol };
/** Receiver-owned delivery identity; independent of reusable producer frame IDs. */
export type FrameForwardingDeliveryId = number & { readonly __frameForwardingDeliveryId: unique symbol };
/** Opaque credential that lets any holder connect a producer to one channel; never a renderer-facing value or log field. */
export type FrameForwardingTx = string & { readonly __frameForwardingTx: unique symbol };
/** Increasing, never reused identity of one producer connection within its channel. */
export type FrameForwardingConnectionId = number & { readonly __frameForwardingConnectionId: unique symbol };
/** Receiver notifications on the JavaScript thread. Every connection event names its connection. */
export type FrameForwardingEvent =
  /** A producer holding the TX credential received ready; its frames follow. */
  | { type: 'connected'; connectionId: FrameForwardingConnectionId; pid: number }
  | { type: 'frame'; connectionId: FrameForwardingConnectionId; frameId: number; deliveryId: FrameForwardingDeliveryId; width: number; height: number; stride: number; metadata: string; adapterId: FrameForwardingAdapterId;
      transport: 'shared-texture'; handle: Buffer;
      /** Actual source descriptor declares key-0 synchronization; false for legacy producers and macOS. */
      sourceKeyedMutex: boolean;
      /** Windows adapter owning the output texture; null for macOS IOSurface. */
      presentationAdapterId: FrameForwardingAdapterId | null }
  | { type: 'message'; connectionId: FrameForwardingConnectionId; text: string }
  /** The producer left or failed; text is empty after its goodbye. Delivered frames stay valid and the connection drains. */
  | { type: 'disconnected'; connectionId: FrameForwardingConnectionId; text?: string }
  /** Every frame and resource of the connection was released; a waiting successor connects next. */
  | { type: 'drained'; connectionId: FrameForwardingConnectionId }
  /** GPU completion is unknown, so the connection keeps its resources and budget and its drain waits. */
  | { type: 'drain-blocked'; connectionId: FrameForwardingConnectionId; text: string }
  /**
   * A candidate was refused: channel-busy, transferable-tx-required, producer-local-handles-required, invalid-credential, channel-closed, protocol-mismatch
   * naming both protocol versions, or a setup failure.
   */
  | { type: 'rejected'; text: string }
  /** The channel stopped accepting producers; close it. */
  | { type: 'failed'; text: string };
/**
 * One frame-forwarding channel: a stable listener serving one producer connection at a time. A connection's frames,
 * allocations, credit and GPU relay state belong to it; after it disconnects they drain before the next producer
 * holding the TX credential receives ready. Frame resources remain retained until explicit release. GC and Worker
 * termination request asynchronous native cleanup.
 */
export interface FrameForwardingReceiver {
  /** Transferable credential: any process holding a copy may connect; pass it only to trusted producers. */
  readonly tx: FrameForwardingTx;
  /** Send application JSON to one connection; throws unless it is the connected one, or above 16383 UTF-8 bytes. */
  send(connectionId: FrameForwardingConnectionId, json: string): void;
  /** Release after Electron allReferencesReleased; credit returns only to the frame's own connection. Duplicate releases return false. */
  release(deliveryId: FrameForwardingDeliveryId): boolean;
  /**
   * Close the channel: the listener stops, so the TX credential no longer connects, and the current connection ends.
   * Asynchronously awaits GPU completion or confirmed device removal and worker exit. Outstanding delivered frames
   * remain owned until release(). Unfinished copies retain their resource and budget reservations.
   * A stalled driver can leave this promise and Worker termination pending; operation deadlines do not establish GPU completion.
   */
  close(): Promise<void>;
}
/** Opaque shared allocation budget, including producer idle surface pools. */
export interface FrameForwardingBudget { readonly __frameForwardingBudget: unique symbol }
/** Create one budget per window and share it among that window's receivers. */
export function createBudget(maxBytes: number): FrameForwardingBudget;
/** Create a channel whose producer allocations reserve bytes from the shared budget. */
export function createReceiver(options: {
  maxFrames: number; maxBytes: number; budget: FrameForwardingBudget;
  /** Electron's actual adapter for shared-texture on Windows; null on macOS. */
  displayAdapter: FrameForwardingAdapterId | null;
  /** Total queued GPU readback/upload deadline, also bounding a connected client's handshake. Expiry ends the connection; safe resource retirement may take longer. */
  readbackTimeoutMs: number;
  /** Ordered by default; latest permits replacing pending full-frame images. */
  framePolicy?: 'ordered' | 'latest';
}, onEvent: (event: FrameForwardingEvent) => void): FrameForwardingReceiver;
/** Identify the GPU owning a borrowed native texture handle; null means unavailable. */
export function getAdapter(handle: Buffer): FrameForwardingAdapterId | null;

/** Native worker notifications delivered serially on the creating JavaScript thread. */
export type FrameForwardingProducerEvent = { type: 'message' | 'error'; text: string } | { type: 'closed' };
/** An acquired surface remains owned until submit, discard, or producer close; GC never releases it. */
export interface FrameForwardingProducerSurface {
  readonly width: number;
  readonly height: number;
  /**
   * Upload premultiplied BGRA8 pixels on the native worker. Concurrent surface operations reject.
   * @param pixels Non-shared Buffer retained until settlement; do not modify, detach, or transfer its backing store meanwhile.
   * @param stride Bytes between rows, at least width * 4; the buffer must cover the last complete row.
   * @returns Resolves when input bytes are copied and may be reused; Windows GPU completion is asynchronous. Failure may close the producer.
   */
  writeBgra(pixels: Buffer, stride: number): Promise<void>;
  /**
   * Transfer the frame to the receiver; a successful call consumes this lease.
   * @param frameId Positive safe integer, unique among outstanding frames.
   * @param metadata Application JSON, at most 16383 UTF-8 bytes with no NUL.
   * @returns Resolves on native submission, not display or receiver release.
   */
  submit(frameId: number, metadata: string): Promise<void>;
  /**
   * Transfer the frame as the producer's newest state; a successful call consumes this lease. While all but one of the
   * receiver's surfaces await release, the frame waits in the producer and a newer latest submission replaces it, and a
   * receiver may drop it before presentation once a newer latest frame is ready.
   * @param frameId Positive safe integer, unique among outstanding frames.
   * @param metadata Application JSON, at most 16383 UTF-8 bytes with no NUL.
   * @returns Resolves on native submission or replacement, not display or receiver release.
   */
  submitLatest(frameId: number, metadata: string): Promise<void>;
  /** @returns Resolves after returning an unsubmitted, idle surface to the pool; busy or consumed leases reject. */
  discard(): Promise<void>;
  /** @returns The same explicit release as discard(); busy or consumed leases reject. */
  close(): Promise<void>;
}
/** Options for a bounded producer worker. Application configuration supplies every limit. */
export interface FrameForwardingProducerOptions {
  /** The channel's TX credential; a parent process may pass it to the producer it starts. */
  tx: FrameForwardingTx | string;
  /** Maximum ordinary operations awaiting completion, including acquisitions; 1–65536. Discard has one reserved slot per owned lease. */
  maxPendingOperations: number;
  /** Positive connection, queue/acquisition, and GPU-wait deadline in milliseconds. */
  operationTimeoutMs: number;
}
/** Producer backed by the C SDK, with explicit asynchronous teardown. */
export interface FrameForwardingProducer {
  /**
   * Resolves after the receiver's ready, which waits while a previous producer of the channel
   * drains; rejects with a message starting "channel-busy" while another producer holds the channel. Queued operations may precede it.
   */
  readonly ready: Promise<void>;
  /** Resolves after worker exit, C client close, and pending operation settlement. */
  readonly closed: Promise<void>;
  /**
   * Wait for native allocation credit without blocking the worker. Discard remains admissible at queue capacity.
   * @param width Positive pixel width, at most 16384.
   * @param height Positive pixel height, at most 16384.
   * @returns An owned surface; acquisition timeout rejects this request and leaves the producer usable.
   */
  acquire(width: number, height: number): Promise<FrameForwardingProducerSurface>;
  /**
   * Queue application control independently of pending acquisitions.
   * @param json Message of at most 16383 UTF-8 bytes with no NUL.
   * @returns Resolves after the native send.
   */
  send(json: string): Promise<void>;
  /**
   * Close this producer's connection: no further operation is sent, unsubmitted frames are dropped, and the receiver
   * drains the frames it holds before a successor with the same TX credential becomes ready.
   * @returns Idempotent closed promise after interrupting connect, poll, and acquisition waits.
   */
  close(): Promise<void>;
}
/**
 * Create a C-SDK producer worker without blocking the JavaScript event loop.
 * @param options TX credential and explicit limits.
 * @param onEvent Message/error/closed listener; listener exceptions are contained so teardown can complete.
 * @returns A producer requiring explicit close; its native worker keeps the process alive.
 */
export function createProducer(options: FrameForwardingProducerOptions, onEvent: (event: FrameForwardingProducerEvent) => void): FrameForwardingProducer;
